import pandas as pd

def clean(df):
    df = df.copy()
    # Normalize text labels (strip spaces, standardize case)
    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype(str).str.strip().str.lower()
    df['species'] = df['species'].replace({'adelie': 'Adelie', 'chinstrap': 'Chinstrap', 'gentoo': 'Gentoo'})
    df['island'] = df['island'].replace({'biscoe': 'Biscoe', 'dream': 'Dream', 'torgersen': 'Torgersen'})
    df['sex'] = df['sex'].replace({'nan': None, 'none': None})
    # Convert body_mass_g (text with commas) to numeric
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    # Coerce other numeric columns just in case they arrive as text
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # Drop rows with unparseable/missing body mass or species
    df = df.dropna(subset=['body_mass_g', 'species'])
    return df

def answer(df):
    df = clean(df)
    grouped = df.groupby('species')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in grouped.items()}
